// Match the requested company against the clients list.
// Trigger email: subject like 'send portal <company name or slug>'
const trig = $('Send-Portal Email Received').first().json;
const fromRaw = String(trig.From || trig.from || (trig.headers && trig.headers.from) || '');
const subject = String(trig.Subject || trig.subject || (trig.headers && trig.headers.subject) || '');
const staffEmail = (fromRaw.match(/[\w.+-]+@[\w.-]+/) || [''])[0].toLowerCase();
const clients = $input.all().map(i => i.json).filter(c => c && c.slug);
const hay = subject.toLowerCase();
let matched = null;
for (const c of clients) {
  if ((c.name && hay.includes(String(c.name).toLowerCase())) || (c.slug && hay.includes(String(c.slug).toLowerCase()))) { matched = c; break; }
}
const isStaff = staffEmail.endsWith('@think-technologies.com');
return [{ json: { ok: !!(matched && isStaff), reason: !isStaff ? 'sender not @think-technologies.com' : (!matched ? 'no client name in subject matched the client list' : ''), staffEmail, subject, client_id: matched ? matched.id : null, client_name: matched ? matched.name : null, slug: matched ? matched.slug : null } }];

const m = $('Match Client').first().json;
const inv = ($json && $json.email) ? $json.email : null;
return [{ json: Object.assign({}, m, { clientEmail: inv, ok: m.ok && !!inv, reason: m.ok && !inv ? 'client has no login email — set it in the admin panel first' : m.reason }) }];

